parameters.new_string:
/** Tears every socket and server down, so a red test reports instead of hanging the run. */
export async function stopEngines(): Promise<void> {
  await Promise.all(clients.splice(0).map(closeClient));
  await Promise.all(servers.splice(0).map(closeServer));
}

async function closeClient(client: WebSocket): Promise<void> {
  if (client.readyState === WebSocket.CLOSED) return;
  const closed = once(client, 'close');
  client.terminate();
  await closed;
}

async function closeServer(hal: HalServer): Promise<void> {
  const openSockets = [...hal.wss.clients].filter(socket => socket.readyState !== WebSocket.CLOSED);
  const closed = Promise.all(openSockets.map(socket => once(socket, 'close')));
  await hal.stop();
  await closed;
}

